package com.foodbridge.repository;
import com.foodbridge.model.*; import org.springframework.data.jpa.repository.JpaRepository; import java.util.*;
public interface DonationRepository extends JpaRepository<Donation,Long> { List<Donation> findByDonorId(Long id); List<Donation> findByStatus(DonationStatus status); long countByStatus(DonationStatus status); long countByDonorId(Long donorId); long countByDonorIdAndStatus(Long donorId, DonationStatus status); }